/**
 * Traduce el nombre de cualquier arma al idioma activo (es, en, pt, ja, ko).
 * Maneja nombres combinados con barra (ej. "Aqua Simulacra / Alas Celestiales")
 * y nombres con paréntesis en español/inglés (ej. "Huso de Cinabrio (Cinnabar Spindle)").
 */
function getWeaponTranslatedName(rawName, lang) {
  if (!rawName) return "";
  const curLang = lang || (typeof state !== "undefined" && state.lang) || "es";
  const str = String(rawName).trim();

  // Si contiene barra "/", traducir ambas armas por separado
  if (str.includes(" / ")) {
    return str.split(" / ").map((part) => getWeaponTranslatedName(part.trim(), curLang)).join(" / ");
  }

  // Buscar coincidencia exacta directa en el diccionario
  const low = str.toLowerCase();
  if (I18N_WEAPONS_RAW[low]) {
    return I18N_WEAPONS_RAW[low][curLang] || I18N_WEAPONS_RAW[low].en || str;
  }

  // Si tiene sufijo de refinamiento (ej. "R5")
  const rMatch = str.match(/\s+(R[1-5])\b/i);
  const rSuffix = rMatch ? " " + rMatch[1].toUpperCase() : "";
  const baseNoR = str.replace(/\s+R[1-5]\b/i, "").trim().toLowerCase();
  if (I18N_WEAPONS_RAW[baseNoR]) {
    return (I18N_WEAPONS_RAW[baseNoR][curLang] || I18N_WEAPONS_RAW[baseNoR].en || str) + rSuffix;
  }

  // Si viene en formato "Nombre Español (English Name)"
  const parenMatch = str.match(/^(.*?)\s*\((.*?)\)$/);
  if (parenMatch) {
    const esPart = parenMatch[1].trim().toLowerCase();
    const enPart = parenMatch[2].trim().toLowerCase();
    const targetObj = I18N_WEAPONS_RAW[enPart] || I18N_WEAPONS_RAW[esPart];
    if (targetObj) {
      return (targetObj[curLang] || targetObj.en || str) + rSuffix;
    }
    // Si no está en el diccionario y el idioma es inglés, devolver la parte entre paréntesis
    if (curLang === "en") return parenMatch[2].trim() + rSuffix;
    if (curLang === "es") return parenMatch[1].trim() + rSuffix;
  }

  // Búsqueda por coincidencia parcial si es un alias
  for (const k in I18N_WEAPONS_RAW) {
    if (k.length > 4 && (low.includes(k) || k.includes(low))) {
      return (I18N_WEAPONS_RAW[k][curLang] || I18N_WEAPONS_RAW[k].en || str) + rSuffix;
    }
  }

  return str;
}

/**
 * Traduce el nombre de cualquier set de artefactos al idioma activo.
 * Maneja cantidad de piezas (ej. "4 piezas", "2 piezas").
 */
function getArtifactTranslatedName(rawSet, lang) {
  if (!rawSet) return "";
  const curLang = lang || (typeof state !== "undefined" && state.lang) || "es";
  const str = String(rawSet).trim();

  // Detectar 4 piezas o 2 piezas
  const is4p = /4\s*(piezas|peças|p|セット|세트|piece)/i.test(str);
  const is2p = /2\s*(piezas|peças|p|セット|세트|piece)/i.test(str);
  const pieceSuffix = {
    es: is4p ? " (4 piezas)" : (is2p ? " (2 piezas)" : ""),
    en: is4p ? " (4-Piece)" : (is2p ? " (2-Piece)" : ""),
    pt: is4p ? " (4 Peças)" : (is2p ? " (2 Peças)" : ""),
    ja: is4p ? " (4セット)" : (is2p ? " (2セット)" : ""),
    ko: is4p ? " (4세트)" : (is2p ? " (2세트)" : "")
  }[curLang] || "";

  // Limpiar sufijos
  const cleanBase = str
    .replace(/\(.*?\)/g, "")
    .replace(/[42]\s*(piezas|peças|p|セット|세트|piece)/gi, "")
    .replace(/\/.*$/, "")
    .trim()
    .toLowerCase();

  if (I18N_ARTIFACTS_RAW[cleanBase]) {
    const artObj = I18N_ARTIFACTS_RAW[cleanBase];
    return (artObj[curLang] || artObj.en || cleanBase) + pieceSuffix;
  }

  // Buscar coincidencia parcial
  for (const k in I18N_ARTIFACTS_RAW) {
    if (k.length > 4 && cleanBase.includes(k)) {
      const artObj = I18N_ARTIFACTS_RAW[k];
      return (artObj[curLang] || artObj.en || cleanBase) + pieceSuffix;
    }
  }

  return str;
}

/**
 * Traduce el nombre de un personaje al idioma activo (para compañeros de equipo y tarjetas).
 */
function getCharacterTranslatedName(rawChar, lang) {
  if (!rawChar) return "";
  const curLang = lang || (typeof state !== "undefined" && state.lang) || "es";
  const low = String(rawChar).trim().toLowerCase();
  if (I18N_CHARACTERS_RAW[low]) {
    return I18N_CHARACTERS_RAW[low][curLang] || I18N_CHARACTERS_RAW[low].en || rawChar;
  }
  return rawChar;
}

